<template><view class="statement"><view class="card"><text class="heading">企业对账</text><view class="row"><text>开始日期</text><picker mode="date" :value="from" @change="from=$event.detail.value"><text>{{from}} ›</text></picker></view><view class="row"><text>结束日期</text><picker mode="date" :value="to" @change="to=$event.detail.value"><text>{{to}} ›</text></picker></view><button class="ui-button" :disabled="busy" @click="act(load)">查询明细</button></view><view v-if="error" class="card">{{error}}</view><template v-if="data"><view class="card"><text class="heading">账期应收核对</text><view>期初应还 ¥{{money(data.opening)}}</view><view>＋ 本期账期采购 ¥{{money(data.creditPurchases)}}</view><view>－ 已核销还款 ¥{{money(data.repayments)}}</view><view>－ 退款冲减 ¥{{money(data.creditRefunds)}}</view><view>＝ 期末应还 ¥{{money(data.closing)}}</view><text class="hint">普通付款、银行收退和非实收记录分别列在下方明细，不重复加入账期应收。</text><button class="ui-button" :disabled="busy" @click="download">导出Excel对账单</button><button class="ui-button" :disabled="busy||data.confirmed" @click="confirm">{{data.confirmed?'本期数据已确认':'确认本期核对无误'}}</button><text v-if="!data.confirmed&&data.confirmations.length" class="hint">本期存在新的数据变化，请重新核对。以前的确认记录仍保留。</text></view><view v-for="i in data.issues" :key="i.id" class="card"><text>{{i.status==='open'?'待处理差异':'已处理差异'}}：{{i.note}}</text><view v-if="i.resolution">处理说明：{{i.resolution}}</view><template v-if="i.status==='open'"><input v-model="resolutions[i.id]" placeholder="填写已核实的处理结果"/><button class="ui-button" :disabled="busy" @click="resolve(i)">确认差异已处理</button></template></view><view v-for="r in data.rows" :key="r.event_key" class="card"><view>{{kindName(r.kind)}} · ¥{{money(r.amount)}}</view><view>订单 {{r.order_no}}</view><text class="hint">{{formatDate(r.occurred_at)}} · {{r.note}}</text><button class="ui-button" v-if="selected!==r.event_key" :disabled="busy" @click="selected=r.event_key;note=''">这笔有疑问</button><template v-else><input v-model="note" placeholder="说明哪处对不上"/><button class="ui-button" :disabled="busy" @click="issue(r)">标记差异</button></template></view><text v-if="!data.rows.length" class="hint">该期间没有交易记录。</text></template></view></template>
<script>
import {refreshOnTick} from '../services/panel-refresh'
import {request,money,notify,API_BASE,getToken} from '../services/shop.js'
import {formatDate} from '../services/display'
const date=d=>d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')
export default {mixins:[refreshOnTick()],data(){const now=new Date();return{from:date(new Date(now.getFullYear(),now.getMonth(),1)),to:date(now),data:null,error:'',busy:false,note:'',selected:'',resolutions:{},names:{purchase:'账期采购',repayment:'核销还款',refund:'退款冲应收',bank_transfer_payment:'对公订单付款',bank_transfer_refund:'对公订单退款',simulation_payment:'非实收订单记录',simulation_refund:'非实收退款记录',wechat_payment:'微信订单付款',wechat_refund:'微信订单退款',wallet_payment:'余额订单付款',wallet_refund:'余额订单退款',rebate_payment:'返利抵扣订单付款',rebate_refund:'返利抵扣订单退款',points_exchange_payment:'积分兑换订单付款',points_exchange_refund:'积分兑换订单退款',bank_received:'银行实际收款核验',bank_outcome:'银行实际退款确认',bank_return:'银行实际退款确认'}}},mounted(){this.load()},methods:{money,formatDate,kindName(kind){return this.names[kind]||'订单收退款'},async load(){try{this.data=await request('/company/statement?from='+this.from+'&to='+this.to);this.error=''}catch(e){this.error=e.message;this.data=null}},async act(fn){if(this.busy)return;this.busy=true;try{await fn()}catch(e){notify(e)}finally{this.busy=false}},issue(r){this.act(async()=>{await request('/company/statement/issues','POST',{from:this.data.from,to:this.data.to,eventKey:r.event_key,note:this.note});this.selected='';await this.load()})},resolve(i){this.act(async()=>{await request('/company/statement/issues/'+i.id+'/resolve','POST',{note:this.resolutions[i.id]||''});await this.load()})},confirm(){this.act(async()=>{await request('/company/statement/confirm','POST',{from:this.data.from,to:this.data.to,hash:this.data.hash});await this.load()})},download(){this.act(async()=>{const url=API_BASE+'/shop/app/company/statement/export?from='+this.data.from+'&to='+this.data.to;const header={'X-Shop-Token':'Bearer '+getToken()};
// #ifdef H5
const res=await fetch(url,{headers:header});if(!res.ok||!res.headers.get('content-type')?.includes('spreadsheetml'))throw Error('导出失败，请重新登录后重试');const blob=await res.blob();const href=URL.createObjectURL(blob),a=document.createElement('a');a.href=href;a.download='企业对账_'+this.data.from+'_'+this.data.to+'.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(href),1000);
// #endif
// #ifndef H5
await new Promise((resolve,reject)=>uni.downloadFile({url,header,success:r=>{if(r.statusCode!==200)return reject(Error('导出失败，请重新登录后重试'));uni.openDocument({filePath:r.tempFilePath,fileType:'xlsx',showMenu:true,success:resolve,fail:()=>reject(Error('无法打开文件，请重试'))})},fail:()=>reject(Error('导出失败，请检查网络'))}));
// #endif
})}}}
</script>
<style scoped>
@import '../styles/component-base.css';
.statement{padding:16px;font-size:16px}.card{background:var(--shop-surface, #fdfeff);border-radius:12px;padding:16px;line-height:1.8;margin-bottom:14px}.heading{font-size:20px;font-weight:bold;display:block}.row{display:flex;justify-content:space-between;padding:10px 0}.hint{color:var(--shop-ink, #28546c);font-size:14px;display:block}input{padding:12px;margin:10px 0;background:var(--shop-background, #f3f8fb)}button{font-size:16px;margin-top:12px;color:var(--shop-ink, #28546c);background:var(--shop-accent, #c7e8f5)}</style>
